// GetUpscaleOnExclusion checks if excluded workloads should be upscaled.
func (s Scopes) GetUpscaleOnExclusion() bool {
	for _, scope := range s {
		if scope.hasUpscaleOnExclusion() {
			return true
		}
	}

	return false
}

func (s *Scope) hasUpscaleOnExclusion() bool {
	return s.UpscaleOnExclusion.isSet && s.UpscaleOnExclusion.value
}

// GetExcluded checks if the scopes exclude scaling and whether exclusions should upscale.
func (s Scopes) GetExcluded() (bool, bool) {
	excluded, _ := s.getExcludedBy(
		func(scope *Scope) bool { return scope.Exclude != nil },
		func(scope *Scope) bool { return scope.Exclude.inTimeSpans() },
	)
	if excluded {
		return true, false
	}

	return s.getExcludedBy(
		func(scope *Scope) bool { return scope.ExcludeUntil != nil },
		func(scope *Scope) bool { return scope.ExcludeUntil.After(time.Now()) },
	)
}

func (s Scopes) getExcludedBy(exclusionIsSet, exclusionApplies func(*Scope) bool) (bool, bool) {
	upscaleOnExclusion := false

	for _, scope := range s {
		if scope.hasUpscaleOnExclusion() {
			upscaleOnExclusion = true
		}

		if !exclusionIsSet(scope) {
			continue
		}

		if exclusionApplies(scope) && !upscaleOnExclusion {
			return true, false
		}

		break
	}

	return false, upscaleOnExclusion
}

